update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-poitiers/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Poitiers et dans la Vienne","mecanisme":"La Vienne aligne trois parcs qui n''ont rien en commun. La mécanique de précision de Châtellerault, les plateformes logistiques des axes du Futuroscope, les installations de carrières où la poussière abrase tout. Le même prestataire doit savoir mesurer au centième et remplacer un palier plein de fines. Nos techniciens se déplacent partout en France.","cta":"Demander une intervention à Poitiers","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7, en option, couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients accompagnés en France, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus à l''issue d''un entretien technique et comportemental"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens mobiles partout en France"}]},{"type":"probleme","punchline":"Un centre d''usinage à grande vitesse s''arrête. La pièce de précision ne sort pas, et le donneur d''ordre qui attend, lui, ne déplace pas sa date.","puces":[{"accroche":"La précision se perd sans qu''on la voie partir.","texte":"Sans contrôle géométrique régulier, la dérive apparaît sur la pièce, pas sur la machine."},{"accroche":"La poussière abrasive dévore les organes.","texte":"Concassage, criblage, convoyage de matériaux : roulements et étanchéités vieillissent trois fois plus vite qu''en atelier."},{"accroche":"Les appareils de levage imposent leurs vérifications.","texte":"Un contrôle périodique oublié immobilise un engin au pire moment."},{"accroche":"La logistique des axes vit à l''heure du flux.","texte":"Un convoyeur bloqué se voit sur les expéditions dans l''heure qui suit."},{"accroche":"Les annonces de technicien restent sans réponse des mois.","texte":"Votre équipe absorbe, puis décroche."}]}]'::jsonb) where path = '/implantations/maintenance-industrielle-poitiers/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Contrôle géométrique et remise en précision","texte":"alignements, paliers, broches, reprise de jeux."},"benefice":"Le rebut cesse d''être le signal d''alerte de votre parc d''usinage."},{"prestation":{"accroche":"Suivi renforcé des équipements en ambiance abrasive","texte":"étanchéités, graissage, protections, roulements."},"benefice":"Vous remplacez moins souvent, et vous savez pourquoi quand vous remplacez."},{"prestation":{"accroche":"Levage et manutention pris dans le périmètre mécanique","texte":"organes, contrôles, remise en état."},"benefice":"Les immobilisations réglementaires se planifient au lieu de tomber par surprise."},{"prestation":{"accroche":"Pré-diagnostic à distance avant tout déplacement","texte":"photos, historique, symptômes."},"benefice":"Le technicien part avec les bonnes pièces au lieu de découvrir la panne sur place."},{"prestation":{"accroche":"Couverture multi-technique","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [robotique](/expertises/robotique/), [hydraulique](/expertises/hydraulique/), [soudure et tuyauterie](/expertises/soudure/)."},"benefice":"Une panne qui croise trois métiers mobilise une équipe, pas trois devis."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation de techniciens mobiles partout en France."},"benefice":"Une panne du vendredi soir ne coûte pas le lundi de production."}],"prose":[{"texte":"Pour les entrepôts et plateformes des axes, voir la [maintenance des équipements logistiques](/secteurs/logistique/). Pour les lignes de conditionnement alimentaires, voir la [maintenance en agroalimentaire](/secteurs/agroalimentaire/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la panne","texte":"équipement, symptôme, criticité. Vous recevez un avis franc sur ce que nous savons faire et ce qu''il faut chercher d''abord."},{"titre":"Nous vous rappelons dans l''heure","texte":"qualification du besoin, du profil disponible et des habilitations exigées par votre site."},{"titre":"Le pré-diagnostic évite le déplacement à l''aveugle","texte":"photos, historique, symptômes. Le devis part sur cette base."},{"titre":"L''intervention se déroule sous vos consignes","texte":"accueil sécurité, plan de prévention, consignation, puis diagnostic."},{"titre":"Essais et redémarrage avec votre production","texte":"la remise en service se valide avec vos opérateurs, pas seulement sur le papier."},{"titre":"Le compte rendu part dans votre GMAO","texte":"cause, travaux réalisés, préconisations, organes fatigués signalés."}]},{"type":"garanties","puces":[{"accroche":"Des pièces consultées au prix du marché","texte":"composants d''origine ou équivalents, sans coefficient caché, l''achat reste sous votre contrôle."},{"accroche":"Le profil présenté avant l''arrivée","texte":"10 % des candidats retenus, entretien technique et comportemental, méthode détaillée sur notre page [sélection des techniciens](/ressources/process/selection-des-techniciens/)."},{"accroche":"Aucun délai de route inventé","texte":"rappel dans l''heure aux horaires ouvrés, astreinte 24/24 et 7/7 en option. Le reste dépend de l''adresse exacte du site, annoncé avant tout déplacement."}]},{"type":"cta","question":"Besoin d''un pré-diagnostic avant d''engager une réparation lourde ?","bouton":"Demander une intervention à Poitiers","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-poitiers/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Un technicien intégré à temps plein sur un parc de centres d''usinage, de presses et de machines à commande numérique","texte":"fabrication de pièces mécaniques de précision, 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Un responsable maintenance intégré sur site pendant une montée de cadence","texte":"pilotage du service repris sans rupture, troisième trimestre 2025","lienLibelle":"Étude de cas ERIKS","lienHref":"/preuves/eriks/"},{"titre":"Intervenants intégrés aux équipes sur le contrôle de chantier de projets d''automatisation logistique","texte":"phases critiques sécurisées","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"},{"titre":"1 à 3 techniciens en renfort des équipes maintenance sur plusieurs sites de production, depuis octobre 2024","texte":"disponibilité machine tenue chaque semaine","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"},{"titre":"10 à 20 techniciens une semaine sur deux, par créneaux de 8 heures, sur un centre logistique en continu","texte":"contrat annuel depuis septembre 2022","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Poitiers, alors que votre siège est à Lyon ?","reponse":"Oui, sans publier d''adresse vitrine dans la ville. Nos 4 agences sont Lyon (siège), Montréal, Dubaï et Madrid, et nos techniciens se déplacent partout en France, outillage embarqué. Votre demande est rappelée dans l''heure aux horaires ouvrés. Ce qui décide de votre journée, c''est le niveau du technicien qui arrive, pas la distance d''un bureau."},{"question":"Quelles communes couvrez-vous dans la Vienne ?","reponse":"Poitiers et son agglomération, Saint-Benoît, Fontaine-le-Comte, Chasseneuil-du-Poitou, Jaunay-Marigny, puis Châtellerault et les bassins du département. Vers l''ouest et le sud, la couverture continue jusqu''à Niort, Tours et Bordeaux."},{"question":"Quels équipements prenez-vous en charge ?","reponse":"Les équipements de production avant tout. Machines-outils, lignes de conditionnement, pompes, centrales hydrauliques, compresseurs, convoyeurs, presses, robots, fours et process thermiques. Le levage et la manutention entrent dans le périmètre mécanique. Le multitechnique de bâtiment et la climatisation de confort ne sont pas notre terrain, et nous le disons au premier échange."},{"question":"Comment se passe un premier dépannage ?","reponse":"Un appel, un pré-diagnostic à distance, un devis, puis l''intervention : diagnostic, réparation, essais, compte rendu. Beaucoup de nos contrats réguliers ont commencé par un dépannage réussi, c''est le moyen le plus simple de nous mettre à l''épreuve."},{"question":"Pouvez-vous reprendre un préventif abandonné ?","reponse":"Oui, le cas est fréquent. État des lieux du parc, analyse de l''historique de pannes, plan reconstruit selon l''utilisation réelle. Puis le pilotage : visites planifiées, traçabilité, indicateurs, vérifications périodiques des appareils de levage."},{"question":"Travaillez-vous avec les PME ou seulement les grands groupes ?","reponse":"Les deux. Plus de 120 clients nous font travailler, du groupe national à l''atelier de vingt personnes. L''offre se dimensionne au besoin. Réparation ponctuelle, [contrat Zéro arrêt](/offres/zero-arret/) sur devis, ou technicien intégré à votre équipe en 2 à 3 semaines."}]}]'::jsonb) where path = '/implantations/maintenance-industrielle-poitiers/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"ctaFinal","question":"Besoin d''un parc remis à plat avant de décider du budget de l''année ?","bouton":"Demander une intervention à Poitiers","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-poitiers/';
